// Sibling files are type imports only: each script is compiled standalone, so runtime imports of them wouldn't resolve.
import { readFileSync } from "node:fs";

import type { WidgetContext, WidgetFieldValue, WidgetMount, WidgetQueryResult } from "../_lib/widget_context";

// Who's online, out of Valheim's ten, over a campfire: the world's name, and the players under it.
// The card folds back to the plain one while nobody is, as Plex's does while nothing plays. The
// join code rides along for the Settings tab.
//
// The join code. A crossplay server logs its code when it registers, again when it replaces it
// (two seconds later on demeter), and when its session becomes active:
//   Session "HexOS Valheim" registered with join code 144343
//   Created new join code 282677 for session "HexOS Valheim"
//   Session "HexOS Valheim" with join code 282677 and IP 203.0.113.7:2456 is active with 0 player(s)
// The image's log filter writes the latest such line to /config/hexos-session.txt (the script's
// VALHEIM_LOG_FILTER_CONTAINS_HexosSession and _HexosNewCode). No file means the server isn't ready:
// it's still starting, and the code reads empty.
//
// The players. The server's own count can't be trusted: when a player quit on demeter (2026-10-30)
// it logged "Player connection lost ... now 1 player(s)" and never logged the drop. What it does log
// is a character spawning, with the player's peer id as the first part of its id, and, once the
// player is gone, each of their objects being cleared, with that same peer as the owner:
//   Got character ZDOID from Odvar Firebear : 1590326189:5
//   Destroying abandoned non persistent zdo 1590326189:5 owner 1590326189
// Dying logs the character as 0:0, and respawning logs a new one under the same peer. The filter
// appends both kinds to /config/hexos-players.txt (_HexosPlayerIn, _HexosPlayerOut), and
// PRE_SERVER_RUN_HOOK removes both files before each start, so a restart begins with nobody on.
//
// The world. PRE_SERVER_RUN_HOOK also writes the world the server runs (its WORLD_NAME) to
// /config/hexos-world.txt; a server started by script 1.1.0 or older has none, and reads "Valheim".
//
// Reading them. The files sit on the app's own dataset, and the HexOS container can't see that on
// every box: a box whose app config predates the pool mounts sees only pool roots and shares, and
// one without rslave has an empty folder in the dataset's place (a production box, 2026-10-31: the
// server up with a code and a player on, and the card and the Settings tab blank). Docker can always
// see them, so a file the mount doesn't give is read out of the app's container over the daemon
// socket the HexOS container has for its host commands.

const SESSION_FILE = "/hexos-session.txt";
const PLAYERS_FILE = "/hexos-players.txt";
const WORLD_FILE = "/hexos-world.txt";
const DOCKER_SOCKET = "/var/run/docker.sock";
/** Under the widget's 5 s timeout, so a stuck daemon reads as nothing rather than failing the card. */
const DOCKER_TIMEOUT_MS = 2000;
/** A dedicated Valheim server takes ten players. */
const MAX_PLAYERS = 10;
// Anchored at the end, or at the code itself, so a server name with "join code 12" in it is never read as one
const JOIN_CODE_LINES = [
  /Session ".*" registered with join code (\d+)$/,
  /: Created new join code (\d+) for session ".*"$/,
  /Session ".*" with join code (\d+) and IP \S+ is active with \d+ player\(s\)$/,
];
const SPAWNED = /: Got character ZDOID from (.+) : (-?\d+):\d+$/;
const CLEARED = /: Destroying abandoned non persistent zdo -?\d+:\d+ owner (-?\d+)$/;

const configMount = (mounts: WidgetMount[]): WidgetMount | undefined =>
  mounts.find((m) => m.containerPath === "/config") ?? mounts.find((m) => m.hostPath.endsWith("/valheim/config"));

const lines = (text: string): string[] => text.split("\n").map((line) => line.trimEnd());

/** The newest join code in the file's text, or null when it names none yet. */
export function joinCode(text: string): string | null {
  for (const line of lines(text.trimEnd()).reverse()) {
    for (const pattern of JOIN_CODE_LINES) {
      const code = pattern.exec(line)?.[1];
      if (code) return code;
    }
  }
  return null;
}

/** The characters on the server, in the order they arrived, from the players file's text. */
export function players(text: string): string[] {
  // By peer, since two players may share a character name; a name seen again under a new peer is
  // the same player back after a leave the log never showed
  const online = new Map<string, string>();
  for (const line of lines(text)) {
    const spawned = SPAWNED.exec(line);
    if (spawned) {
      const [, name, peer] = spawned;
      if (peer === "0") continue; // died: still on, and respawning under the same peer
      for (const [other, otherName] of online) if (otherName === name && other !== peer) online.delete(other);
      online.set(peer, name);
      continue;
    }
    const owner = CLEARED.exec(line)?.[1];
    if (owner) online.delete(owner);
  }
  return [...online.values()];
}

/** Who's online in a line: "Odvar Firebear, June Fireshield, and 3 more". */
export function playersLine(names: string[]): string {
  if (names.length <= 2) return names.join(" and ");
  if (names.length === 3) return `${names[0]}, ${names[1]}, and ${names[2]}`;
  return `${names[0]}, ${names[1]}, and ${names.length - 2} more`;
}

/** The file in a tar from Docker's archive endpoint: a 512-byte header, then its bytes. */
export function untar(tar: Uint8Array): string {
  const text = new TextDecoder();
  for (let at = 0; tar[at]; ) {
    const size = Number.parseInt(text.decode(tar.subarray(at + 124, at + 136)), 8);
    const type = tar[at + 156];
    if (type === 0 || type === 48) return text.decode(tar.subarray(at + 512, at + 512 + size)); // a regular file
    at += 512 + Math.ceil(size / 512) * 512; // a pax header ahead of the file
  }
  return "";
}

async function readThroughDocker(appId: string, path: string): Promise<string> {
  const url = `http://docker/containers/ix-${appId}-${appId}-1/archive?path=${encodeURIComponent(path)}`;
  try {
    const response = await fetch(url, { unix: DOCKER_SOCKET, signal: AbortSignal.timeout(DOCKER_TIMEOUT_MS) });
    return response.ok ? untar(new Uint8Array(await response.arrayBuffer())) : "";
  } catch {
    return ""; // a box with no socket yet
  }
}

async function read(ctx: WidgetContext, mount: WidgetMount | undefined, file: string): Promise<string> {
  if (mount) {
    try {
      return readFileSync(mount.localPath + file, "utf-8");
    } catch {
      // Not written yet, or the dataset isn't visible from here
    }
  }
  return readThroughDocker(ctx.appId, (mount?.containerPath ?? "/config") + file);
}

export async function run(ctx: WidgetContext): Promise<WidgetQueryResult> {
  const config = configMount(ctx.mounts);
  const [playersFile, sessionFile, worldFile] = await Promise.all(
    [PLAYERS_FILE, SESSION_FILE, WORLD_FILE].map((file) => read(ctx, config, file)),
  );
  const names = players(playersFile);
  const code = joinCode(sessionFile);
  const world = worldFile.trim() || "Valheim";
  const fields: Record<string, WidgetFieldValue> = {
    // One entry while anyone's on: the world's name in bold, the players in the small line under it
    online: { type: "list", entries: names.length ? [{ title: world, subtitle: playersLine(names), image: CAMPFIRE }] : [] },
    count: { type: "stat", label: "Players", value: `${names.length}/${MAX_PLAYERS}` },
  };
  // Empty until the server has one, which the Settings tab shows as still to come
  fields.code = { type: "stat", label: "Join code", value: code ?? "" };
  return { fields };
}

// Two Vikings at a campfire, from Valheim's key art: cropped to the card's shape at twice its size
// (1320x520) and WebP at quality 75, to fit the platform's 60,000-character cap on an image field.
const CAMPFIRE =
  "data:image/webp;base64,";
